INSERT INTO public.places (slug, name, description, short_desc, category_id, address, postcode, lat, lng, website, admission, min_age_months, max_age_years, facilities, is_free, is_indoor, is_dog_friendly, area, approved) VALUES
('jubilee-park-waterlooville', 'Jubilee Park Playground', 'A large, well-maintained playground in the heart of Waterlooville town centre. Features a dedicated toddler zone with low swings, small climbing frames, a sandpit and springy animals. The adjacent park has plenty of open grass for picnics and a small café nearby. Very popular on weekday mornings with parent and toddler groups.', 'Large playground with dedicated toddler zone, sandpit and open green space.', 1, 'Jubilee Park, London Road, Waterlooville', 'PO7 7DT', 50.8812, -1.0287, NULL, 'Free', 0, 8, ARRAY['toilets','parking','cafe_nearby','open_space'], true, false, true, 'Waterlooville', true),
('staunton-country-park', 'Staunton Country Park', 'A stunning 1,000-acre country park that is an absolute gem for toddlers. The walled kitchen garden houses animals including goats, peacocks, and donkeys that toddlers can meet up close. There are wide, flat paths ideal for pushchairs, a fairy-tale Gothic conservatory, and a large adventure playground. The tearoom serves excellent cakes. Ranked as one of Hampshire''s best family days out.', 'Magnificent country park with animals, adventure play and pushchair-friendly paths.', 2, 'Middle Park Way, Havant', 'PO9 5HB', 50.8654, -0.9856, 'https://www.hants.gov.uk/staunton', 'Free entry; car park £3-£5', 0, 10, ARRAY['toilets','parking','cafe','baby_change','picnic_area','farm_animals'], false, false, true, 'Havant', true),
('the-base-hayling-island', 'The Base Play & Activity Centre', 'Indoor soft play and activity centre on Hayling Island, just minutes from Havant. Purpose-built for under-5s with separate baby and toddler areas with soft foam equipment, ball pool, and slides. A relaxed café-style seating area lets parents catch up while kids play safely. Runs regular themed sessions.', 'Dedicated indoor soft play for babies and toddlers with café.', 4, 'Sinah Lane, Hayling Island', 'PO11 0HQ', 50.8005, -0.9990, NULL, '£5.50 child, free under 12 months', 0, 5, ARRAY['toilets','parking','cafe','baby_change','baby_area'], false, true, false, 'Havant', true),
('southwick-country-park', 'Southwick Country Park & Playground', 'A beautiful, largely undiscovered country park near Fareham with a brilliant adventure playground at its heart. The playground has a toddler section with swings, small slides and a balance trail. Woodland walking trails with wide, mostly flat paths are great for young walkers. Bluebells in spring make it magical. Quiet, never overcrowded.', 'Peaceful country park with toddler playground and woodland walks.', 2, 'Southwick Road, Southwick, Fareham', 'PO17 6EE', 50.8879, -1.1234, NULL, 'Free', 0, 10, ARRAY['toilets','parking','picnic_area','open_space'], true, false, true, 'Fareham', true),
('titchfield-haven-nature-reserve', 'Titchfield Haven National Nature Reserve', 'One of Hampshire''s finest nature reserves sitting at the mouth of the River Meon near Fareham. Toddlers absolutely love the ducks, swans and wading birds visible from the hides and pathways. The visitor centre has interactive exhibits sized for small children. Pushchair-friendly main path along the river. Free entry to the grounds.', 'Wonderful wetland nature reserve with birds and a toddler-friendly visitor centre.', 2, 'Cliff Road, Hill Head, Fareham', 'PO14 3JT', 50.8327, -1.2156, 'https://www.hants.gov.uk/titchfield', 'Free (hide entry £3)', 0, 10, ARRAY['toilets','parking','visitor_centre','picnic_area'], false, false, true, 'Fareham', true),
('portchester-castle-grounds', 'Portchester Castle & Grounds', 'The outer bailey of this magnificent Roman and Norman castle is free to enter and provides a magical open space for toddlers to run around. The flat grass courtyard is ideal for picnics. English Heritage manages the keep (paid entry) but the outer grounds are always free. Stunning waterfront views over Portsmouth Harbour. Ice cream van visits in summer.', 'Free, stunning castle grounds on the waterfront - perfect for running around.', 7, 'Castle Street, Portchester, Fareham', 'PO16 9QW', 50.8441, -1.1221, 'https://www.english-heritage.org.uk/portchester', 'Free (outer grounds)', 0, 10, ARRAY['toilets','parking','picnic_area','waterfront'], true, false, true, 'Fareham', true),
('sandy-point-hayling-island', 'Sandy Point Beach, Hayling Island', 'A gorgeous sandy beach at the southern tip of Hayling Island that is ideal for toddlers. The water is very shallow at low tide, creating safe paddling lagoons. The sandy beach is clean and has good facilities nearby. The nature reserve walk along the shoreline is pushchair-accessible. Ice cream kiosk in summer. Parking is straightforward.', 'Beautiful shallow sandy beach perfect for toddler paddling and sandcastles.', 6, 'Sandy Point Road, Hayling Island', 'PO11 9SL', 50.7792, -0.9693, NULL, 'Free (parking charge)', 0, 10, ARRAY['toilets','parking','beach','picnic_area'], true, false, true, 'Havant', true),
('fun-station-waterlooville', 'Fun Station Soft Play, Waterlooville', 'Popular indoor soft play centre in Waterlooville with separate areas for toddlers and babies. The toddler zone features low-level slides, ball pools, climbing frames and sensory play areas. Parent seating is well-positioned around the play frame so you never lose sight of your child. Party rooms available. Runs toddler-only morning sessions.', 'Well-loved local soft play with dedicated baby and toddler areas.', 4, 'Stakes Road, Purbrook, Waterlooville', 'PO7 5PL', 50.8648, -1.0445, NULL, '£5 child, free under 12 months', 0, 5, ARRAY['toilets','parking','cafe','baby_change','baby_area'], false, true, false, 'Waterlooville', true),
('havant-park', 'Havant Park & Splash Pad', 'Havant''s main town park features a brilliant outdoor splash pad (water play area) that is completely free to use in summer months. Toddlers love the water jets and spray features. The adjacent playground has equipment for all ages. The park has wide paths ideal for scooters and balance bikes. Regular events and seasonal activities.', 'Town park with free splash pad water play and good playground.', 1, 'New Lane, Havant', 'PO9 2JR', 50.8545, -0.9825, NULL, 'Free', 0, 8, ARRAY['toilets','parking','splash_pad','picnic_area','open_space'], true, false, true, 'Havant', true),
('hollam-bird-garden-fareham', 'Hollam Bird Garden', 'A charming small bird and animal garden near Fareham that is perfectly sized for toddlers. Parrots, owls, meerkats and small mammals in walkthrough enclosures keep young children mesmerised. Compact enough to do in 90 minutes. Staff regularly bring animals out for hands-on interaction. A genuinely lovely, community-feel attraction.', 'Compact bird garden with hands-on animal encounters, perfectly sized for toddlers.', 5, 'Hollam Drive, Titchfield, Fareham', 'PO14 4JJ', 50.8543, -1.2287, NULL, '£6 adult, £5 child', 0, 7, ARRAY['toilets','parking','animal_encounters'], false, false, false, 'Fareham', true),
('west-beach-hayling-island', 'West Beach Hayling Island', 'A long, clean beach stretching the western shore of Hayling Island. The gradual slope into the sea creates excellent shallow paddling at low tide. Beach huts, an ice cream kiosk, and a children''s play area are all nearby. The beach is sandy and gravel-free in parts, making it comfortable for sitting. Popular with local families for crabbing off the jetty.', 'Long, accessible beach with shallow paddling, play area and ice cream.', 6, 'Beach Road, Hayling Island', 'PO11 9PH', 50.7951, -1.0032, NULL, 'Free (pay and display parking)', 0, 10, ARRAY['toilets','parking','beach','playground_nearby','ice_cream'], true, false, true, 'Havant', true),
('fareham-library-rhymetime', 'Fareham Library Rhyme Time', 'Fareham Central Library runs free weekly Rhyme Time and Baby Bounce sessions that are incredibly popular with local dads and toddlers. Sessions typically include 20 minutes of songs, nursery rhymes, and actions followed by free play and a chance to choose library books. Babies from birth welcome. No booking required for most sessions.', 'Free weekly Rhyme Time and Baby Bounce sessions at Fareham Library.', 9, 'Osborn Road, Fareham', 'PO16 7EN', 50.8527, -1.1775, 'https://www.hants.gov.uk/libraries', 'Free', 0, 4, ARRAY['toilets','accessible','baby_area'], true, true, false, 'Fareham', true),
('queen-elizabeth-country-park', 'Queen Elizabeth Country Park', 'Just 5 miles from Waterlooville, this enormous country park in the South Downs National Park is outstanding for family days out. The visitor centre has excellent café facilities. Miles of family cycling trails with bike hire available. The Forest Walk is wide and pushchair-friendly. Stunning views from Butser Hill. The children''s play trail follows a woodland path.', 'Spectacular country park in the South Downs with cycling, trails and great café.', 2, 'Gravel Hill, Horndean, Waterlooville', 'PO8 0QE', 50.9456, -1.0145, 'https://www.hants.gov.uk/qecp', 'Free (car park £3-£5)', 0, 10, ARRAY['toilets','parking','cafe','baby_change','cycling','picnic_area'], false, false, true, 'Waterlooville', true),
('hillhead-rock-pools', 'Hill Head Beach & Rock Pools', 'One of the best rock pooling spots in Hampshire, Hill Head beach near Fareham has extensive rock pools exposed at low tide. Toddlers can find crabs, anemones, shrimps and small fish. The beach itself is shingle but the pools are sand-floored and safe for little ones to paddle in. The nearby Stubbington village has a good pub with garden for lunch.', 'Brilliant rock pooling beach with safe shallow pools and great wildlife.', 6, 'Beach Road, Hill Head, Stubbington', 'PO14 3JJ', 50.8286, -1.2213, NULL, 'Free', 0, 10, ARRAY['parking','beach','picnic_area'], true, false, true, 'Fareham', true),
('meon-valley-trail', 'Meon Valley Trail - Family Cycling', 'The Meon Valley Trail is a converted former railway line providing a completely flat, traffic-free cycling and walking route through gorgeous Hampshire countryside. The section between Wickham and Droxford is perfect for toddlers in bike seats or balance bikes. Very wide tarmac surface, no road crossings, and stunning views across the valley.', 'Flat, traffic-free trail perfect for balance bikes and toddlers in bike seats.', 8, 'Wickham Station Car Park, Mill Lane, Wickham', 'PO17 5DD', 50.9052, -1.1697, NULL, 'Free', 0, 10, ARRAY['parking','cycling','toilets_nearby'], true, false, true, 'Fareham', true),
('leigh-park-community-play', 'Leigh Park Community Play Area', 'A newly renovated community play area in Leigh Park, Havant with excellent facilities for young children. Features a water pump and sand play zone which toddlers find endlessly entertaining, plus a dedicated under-5s enclosed area with soft surface. The adjacent community garden has sensory planting beds at low height. Regular community events and dads'' groups meeting here.', 'Modern community playground with water play, sand and enclosed toddler area.', 1, 'Dunsbury Way, Leigh Park, Havant', 'PO9 5BG', 50.8734, -1.0023, NULL, 'Free', 0, 8, ARRAY['toilets','parking','sand_play','water_play','enclosed_toddler_area'], true, false, false, 'Havant', true),
('wickham-square-river-walk', 'Wickham Village Square & River Walk', 'The picturesque Georgian square of Wickham village is a wonderful spot for a morning out. Toddlers love feeding the ducks on the River Meon just a short walk from the square. The village has excellent independent cafés and a small park. The riverside path is flat and pushchair-friendly. Parking is easy and free on weekends.', 'Gorgeous village with duck-feeding river, great cafés and a lovely park.', 2, 'The Square, Wickham', 'PO17 5JQ', 50.8998, -1.1762, NULL, 'Free', 0, 10, ARRAY['toilets','parking','cafe','duck_feeding','open_space'], true, false, true, 'Fareham', true);
